#include <tiffcraft/TiffExporter.hpp>

#define DOCTEST_CONFIG_IMPLEMENT_WITH_MAIN
#define DOCTEST_CONFIG_DOUBLE_STRINGIFY
#include "doctest.h"

#include <string>
